<?php
declare(strict_types=1);
require_once __DIR__.'/config/bi_step22.php';$error=null;$m=[];$products=[];$customers=[];$coveredRevenue=0.0;$coveredProfit=0.0;$user=[];$p=bi_step22_period($_GET['month']??null);
try{$pdo=business_db();bi_step22_ensure($pdo);$user=bi_step22_guard($pdo,'bi.view');$ctx=bi_step22_context($pdo);$orgId=(int)$ctx['organization_id'];$m=bi_step22_metrics($pdo,$orgId,$p['start'],$p['end']);$products=bi_step22_top_products($pdo,$orgId,$p['start'],$p['end'],20);$customers=bi_step22_top_customers($pdo,$orgId,$p['start'],$p['end'],10);if(business_table_exists($pdo,'product_order_items')){$r=bi_step22_row($pdo,"SELECT COALESCE(SUM(poi.line_price),0) covered_revenue,COALESCE(SUM(poi.line_profit),0) covered_profit FROM product_order_items poi JOIN orders o ON o.id=poi.order_id AND o.organization_id=poi.organization_id JOIN product_sale_ledger sl ON sl.organization_id=o.organization_id AND sl.order_id=o.id AND sl.sale_status='active' WHERE poi.organization_id=? AND o.order_date BETWEEN ? AND ? AND poi.profit_status='explicit_cost'",[$orgId,$p['start'],$p['end']]);$coveredRevenue=(float)($r['covered_revenue']??0);$coveredProfit=(float)($r['covered_profit']??0);}}catch(Throwable $e){$error=$e->getMessage();}
$margin=$coveredRevenue>0?round($coveredProfit/$coveredRevenue*100,2):null;
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Profitability BI - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><link rel="stylesheet" href="assets/bi_step22.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="executive_bi.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>STEP 22 • Verified Profitability</small></span></a><div class="os-top-actions"><a class="os-btn" href="product_cost_basis.php">Cost Basis</a><a class="os-btn primary" href="executive_bi.php">Executive BI</a></div></div></header><main class="os-main" style="max-width:1500px;margin:auto"><section class="os-hero pp-hero"><div class="os-kicker">VERIFIED PROFIT • <?=bi_step22_h($p['label'])?></div><h1>Profit appears only where explicit dated product cost exists.</h1><p>No MRP, discount tier, VP or purchase estimate is silently treated as cost. Margin uses only cost-covered sale lines.</p></section><?php if($error):?><div class="pp-alert bad"><?=bi_step22_h($error)?></div><?php else:?><section class="os-card" style="margin-top:14px"><form method="get" style="display:flex;gap:8px;align-items:end"><div><label class="bi-muted">Month</label><input type="month" name="month" value="<?=bi_step22_h($p['key'])?>" style="display:block;padding:9px;border:1px solid #d8dfda;border-radius:10px"></div><button class="os-btn">Apply</button></form></section><section class="bi-kpis"><div class="bi-kpi"><small>Total Active Sales Revenue</small><strong><?=bi_step22_money($m['sales_revenue'])?></strong><span><?=$m['sales_count']?> sale(s)</span></div><div class="bi-kpi"><small>Cost-Covered Revenue</small><strong><?=bi_step22_money($coveredRevenue)?></strong><span>only explicit-cost lines</span></div><div class="bi-kpi"><small>Verified Profit</small><strong><?=bi_step22_money($coveredProfit)?></strong><span><?=$m['profit_complete_sales']?> complete sale(s)</span></div><div class="bi-kpi"><small>Verified Margin</small><strong><?=$margin===null?'N/A':number_format($margin,2).'%'?></strong><span>covered revenue denominator</span></div><div class="bi-kpi"><small>Deferred-Cost Sales</small><strong><?=$m['profit_deferred_sales']?></strong><span>excluded from verified profit</span></div></section><section class="bi-grid"><article class="os-card bi-span-8"><div class="os-title-row"><div><h2>Product Profitability</h2><p>Line-level profit is shown only on explicit-cost lines.</p></div></div><div class="bi-table-wrap"><table class="bi-table"><thead><tr><th>Stock No.</th><th>Product</th><th>Qty</th><th>Revenue</th><th>VP</th><th>Verified Profit</th><th>Costed Lines</th></tr></thead><tbody><?php if(!$products):?><tr><td colspan="7">No sales in this period.</td></tr><?php endif;?><?php foreach($products as $r):?><tr><td><?=bi_step22_h($r['stock_no'])?></td><td><?=bi_step22_h($r['product_name_snapshot'])?></td><td><?=bi_step22_num($r['qty'],3)?></td><td><?=bi_step22_money($r['revenue'])?></td><td><?=bi_step22_num($r['vp'],3)?></td><td><?=bi_step22_money($r['verified_profit'])?></td><td><?=$r['costed_lines']?> / <?=$r['lines']?></td></tr><?php endforeach;?></tbody></table></div></article><article class="os-card bi-span-4"><div class="os-title-row"><div><h2>Top Customers by Revenue</h2><p>Revenue ranking, not profit attribution.</p></div></div><?php if(!$customers):?><div class="bi-note">No customer-linked sales in this period.</div><?php endif;?><?php foreach($customers as $r):?><div class="bi-note"><b><?=bi_step22_h($r['customer_name'])?></b><strong style="float:right"><?=bi_step22_money($r['revenue'])?></strong><small class="bi-muted"><?=$r['orders']?> order(s) • Receivable <?=bi_step22_money($r['receivable'])?></small></div><?php endforeach;?></article></section><?php endif;?></main></body></html>